namespace sv_8cd3e7f5ca194d5a9075b0b9a6b7888c.Services;

public sealed class WarehouseStateService : IDisposable
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

namespace sv_8cd3e7f5ca194d5a9075b0b9a6b7888c.Services;

/// <summary>
/// Scoped (per-circuit) service that tracks low-stock alert counts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _latestCount;
    private CancellationTokenSource? _pollCts;

    public int LatestCount => _latestCount;

    /// <summary>Raised on the calling thread whenever fresh alert data is available.</summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning the number of low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling every <paramref name="intervalSeconds"/> seconds for the
    /// given warehouse. Only one poll loop runs at a time; calling this again
    /// restarts the loop for a (potentially different) warehouse.
    /// </summary>
    public void StartPolling(Func<string> warehouseIdAccessor, int intervalSeconds = 10)
    {
        StopPolling();
        _pollCts = new CancellationTokenSource();
        var token = _pollCts.Token;

        _ = PollLoopAsync(warehouseIdAccessor, intervalSeconds, token);
    }

    public void StopPolling()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        _pollCts = null;
    }

    private async Task PollLoopAsync(
        Func<string> warehouseIdAccessor, int intervalSeconds, CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(intervalSeconds));

        // Fetch immediately on start, then on each tick.
        await FetchAndNotifyAsync(warehouseIdAccessor());

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync(warehouseIdAccessor());
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal / stop.
        }
    }

    private async Task FetchAndNotifyAsync(string warehouseId)
    {
        _latestCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    public void Dispose()
    {
        StopPolling();
        OnAlertCountChanged = null;
    }
}

